import base64

THUMBNAIL_B64 = """"""

def main():
    output_path = "thumbnail.png"
    image_data = base64.b64decode(THUMBNAIL_B64)
    with open(output_path, "wb") as f:
        f.write(image_data)
    print(f"Thumbnail saved: {output_path}")

if __name__ == "__main__":
    main()
